import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")
    if not database_name:
        raise ValueError("database_name must be a non-empty string.")
    try:
        url_legacy_compatible = webpage_url.find('.internal.') > 0 or webpage_url.startswith('http://localhost')
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(webpage_url, verify=verify_cert)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0] if tree.xpath('//table') else None
        if table is None:
            return 0
        headers = [th.text_content().strip() for th in table.xpath('.//th')]
        rows = []
        for tr in table.xpath('.//tr'):
            tds = tr.xpath('.//td')
            if tds:
                rows.append([td.text_content().strip() for td in tds])
        if not rows:
            return 0
        if headers:
            df = pd.DataFrame(rows, columns=headers)
        else:
            df = pd.DataFrame(rows)
    except Exception as e:
        raise ValueError(f"Error parsing HTML content: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

